import{_ as d,o as a,c as e,ag as r}from"./chunks/framework.CtWPcAmt.js";const u=JSON.parse('{"title":"第 3 章：人与 Agent 怎样分工","description":"人负责目标、取舍、授权与最终责任；Agent 负责检索、整理、生成、执行与重复劳动；监督强度随风险变化。","frontmatter":{"title":"第 3 章：人与 Agent 怎样分工","description":"人负责目标、取舍、授权与最终责任；Agent 负责检索、整理、生成、执行与重复劳动；监督强度随风险变化。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/03-human-agent-division.md","filePath":"guide/03-human-agent-division.md","lastUpdated":null}'),n={name:"guide/03-human-agent-division.md"};function o(i,t,l,h,g,s){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="第-3-章-人与-agent-怎样分工" tabindex="-1">第 3 章：人与 Agent 怎样分工 <a class="header-anchor" href="#第-3-章-人与-agent-怎样分工" aria-label="Permalink to &quot;第 3 章：人与 Agent 怎样分工&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>前两章讲了 Agent 是什么、能做什么。本章回答一个更实际的问题：<strong>一件事到底该谁做？</strong> 用得好的用户不是「把所有事丢给 Agent」，而是有一套稳定的分工原则——知道哪些永远自己定、哪些大胆放手、哪些盯紧一点。本章产出<strong>个人的人机分工表</strong>。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>一位同事让我帮他优化一份给领导的汇报。他把几十页原始材料丢给 Agent，说「帮我总结一下」，然后原样把总结发出去。结果汇报里出现了 Agent 编造的数据——他事后抱怨「AI 太不靠谱」。</p><p>问题不在 Agent。问题在于：<strong>他把「取舍」也交给了 Agent</strong>——哪些数据重要、什么口径、给谁看，这些是人的判断，Agent 不可能替他负责。同样一份材料，如果他把「口径」定清楚，Agent 的总结会很可靠。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>四件事永远是人来定</strong>：目标（做什么、为什么）、取舍（哪个更重要）、授权（允许做什么）、责任（出了问题谁承担）；</li><li><strong>四件事可以放手给 Agent</strong>：检索（找材料）、整理（分类、汇总）、生成（初稿、格式）、执行（按规则做事、重复劳动）；</li><li><strong>监督强度随风险变化</strong>：风险越低越放手，越高越盯紧——不是「要么全自动，要么全手动」；</li><li><strong>好的协作是「人定框架，Agent 填内容，人验收」</strong>，而不是「人出题，Agent 全包」。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>授权（Authorization）</strong>：你明确允许 Agent 做的事的范围。没有授权的行为，哪怕 Agent 自己觉得「顺手做了」，也是越权。</li><li><strong>责任（Accountability）</strong>：最终对结果负责的是人，不是工具。白话解释：实习生办砸了，领导担责的是你。</li><li><strong>监督强度（Supervision level）</strong>：你介入检查的频率与深度。它与风险成正比：L1 低风险任务可以不打扰地跑完，L4 高风险任务每一步都要确认。</li></ul><h2 id="人与-agent-的分工表" tabindex="-1">人与 Agent 的分工表 <a class="header-anchor" href="#人与-agent-的分工表" aria-label="Permalink to &quot;人与 Agent 的分工表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>谁负责</th><th>具体内容</th><th>理由</th></tr></thead><tbody><tr><td>定目标</td><td><strong>人</strong></td><td>要达成什么、做到什么程度</td><td>价值判断，Agent 无法替你定义「好」</td></tr><tr><td>定口径/取舍</td><td><strong>人</strong></td><td>哪些因素重要、冲突时优先什么</td><td>依赖你的场景与偏好</td></tr><tr><td>备材料</td><td>人 + Agent</td><td>人提供入口，Agent 帮助检索/整理</td><td>上下文决定质量（第 11 章）</td></tr><tr><td>定边界</td><td><strong>人</strong></td><td>允许读什么、写什么、能否联网</td><td>授权是你的责任</td></tr><tr><td>规划步骤</td><td>Agent</td><td>拆解步骤、排序</td><td>这正是 Agent 的强项，但你要能看懂计划</td></tr><tr><td>执行</td><td>Agent</td><td>读写文件、生成内容、调用工具</td><td>重复劳动交给机器</td></tr><tr><td>过程监督</td><td>人（按需）</td><td>分段确认、看日志、叫停</td><td>强度随风险（第 9 章）</td></tr><tr><td>验收</td><td><strong>人</strong></td><td>对照标准逐项检查、独立核验</td><td>结果可信度由人把关（第 10 章）</td></tr><tr><td>最终责任</td><td><strong>人</strong></td><td>发布、提交、付款等动作的拍板</td><td>法律与后果由人承担</td></tr></tbody></table><h2 id="跟着做-建立你的分工表" tabindex="-1">跟着做：建立你的分工表 <a class="header-anchor" href="#跟着做-建立你的分工表" aria-label="Permalink to &quot;跟着做：建立你的分工表&quot;">​</a></h2><h3 id="第一步-列出你任务里的所有环节" tabindex="-1">第一步：列出你任务里的所有环节 <a class="header-anchor" href="#第一步-列出你任务里的所有环节" aria-label="Permalink to &quot;第一步：列出你任务里的所有环节&quot;">​</a></h3><p>把序章的任务种子拆成环节（从「收集材料」到「最终交付」）。</p><h3 id="第二步-对照分工表-给每环节标「人-agent-人-agent」" tabindex="-1">第二步：对照分工表，给每环节标「人 / Agent / 人+Agent」 <a class="header-anchor" href="#第二步-对照分工表-给每环节标「人-agent-人-agent」" aria-label="Permalink to &quot;第二步：对照分工表，给每环节标「人 / Agent / 人+Agent」&quot;">​</a></h3><p>诚实一点：标「人」的，是你真的会亲自做的，而不是「反正 Agent 会做」的。</p><h3 id="第三步-标出「必须人工确认点」" tabindex="-1">第三步：标出「必须人工确认点」 <a class="header-anchor" href="#第三步-标出「必须人工确认点」" aria-label="Permalink to &quot;第三步：标出「必须人工确认点」&quot;">​</a></h3><p>在涉及以下动作的环节画 ❗：对外发送、发布、付款、删除、修改重要文件、提供个人信息。这些是硬确认点，第 8 章会展开成权限分级表。</p><h3 id="第四步-为你的任务定「监督档位」" tabindex="-1">第四步：为你的任务定「监督档位」 <a class="header-anchor" href="#第四步-为你的任务定「监督档位」" aria-label="Permalink to &quot;第四步：为你的任务定「监督档位」&quot;">​</a></h3><p>结合第 2 章的委派等级，写一句监督策略，例如：</p><blockquote><p>「材料整理 L1：全程自动，交付后核验边界；最终对外发送 L4：人来做。」</p></blockquote><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>回到我写这本书的真实分工（可对照第 5、6 章的产出过程）：</p><table tabindex="0"><thead><tr><th>环节</th><th>负责人</th><th>实际做法</th></tr></thead><tbody><tr><td>定教程框架与边界</td><td>人</td><td>23 章目录、读者画像、内容边界（<code>docs/00-06</code>）</td></tr><tr><td>七款产品实测</td><td>Agent + 人</td><td>Agent 执行统一基准任务；人记录介入/用时/成本（<code>research/runs/</code>）</td></tr><tr><td>截图分析</td><td>Agent</td><td>视觉模型逐张分析 18 张截图；人审核描述</td></tr><tr><td>界面讲解/产品页写作</td><td>Agent + 人</td><td>Agent 起草十段式正文；人核对事实、标注「未验证」</td></tr><tr><td>横评评分</td><td>人</td><td>六维评分与结论由人依据证据卡给出（<code>docs/12</code>）</td></tr><tr><td>选择结论</td><td><strong>人</strong></td><td>「适合谁」的结论由人下，Agent 只提供证据</td></tr><tr><td>发布决策</td><td><strong>人</strong></td><td>何时合并、何时发布，全部人工确认</td></tr></tbody></table><p>这个例子说明：<strong>Agent 承担了绝大部分「生成」工作，但框架、取舍、评分、发布这些环节始终是人的。</strong> 这也正是这套教程能保持可信的原因。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>「帮我总结一下」原样发出</td><td>把取舍交给了 Agent</td><td>先自己定口径，再让 Agent 按口径总结</td></tr><tr><td>全程不监督，出事后怪 AI</td><td>监督档位没设</td><td>按风险设档，L2 以上分段确认</td></tr><tr><td>每步都打断，Agent 没法干活</td><td>监督过度</td><td>低风险环节设成「完成后汇报」，别事事等确认</td></tr><tr><td>边界没写，Agent 越权</td><td>授权不清</td><td>任务卡写清范围与禁区（第 7 章）</td></tr><tr><td>让 Agent 替自己做决定</td><td>责任错位</td><td>决策留给自己，让 Agent 提供选项与依据</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>你签发的授权，后果由你承担：<strong>不要在没想清楚的情况下放开「全权」</strong>；</li><li>对外发布类动作永远是人的动作，即使内容 90% 是 Agent 生成的；</li><li>涉及医疗、法律、财务：Agent 只出草稿，最终判断必须专业人士。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>20 分钟：按「跟着做」四步完成你的个人分工表（环节 → 负责人 → 确认点 → 监督档位）。路线 B 读者额外思考：哪些环节会成为你的高频重复劳动（那是第四篇模板/Skill 的候选）。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>个人的人机分工表</strong>：任务环节 + 负责人 + 人工确认点 + 监督档位。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>目标、取舍、授权、责任四件事永远是人的；</li><li>检索、整理、生成、执行四件事可以放手；</li><li>监督强度随风险变化，不是非黑即白；</li><li>好的协作：人定框架，Agent 填内容，人验收；</li><li>你已拥有分工表，下一步（第 4 章）选工具。</li></ol>',36)])])}const A=d(n,[["render",o]]);export{u as __pageData,A as default};
